  UNIQUE KEY `uk_activity_enrollment_event_sequence` (`activity_enrollment_id`,`event_sequence`),
  KEY `idx_activity_enrollment_event_session` (`activity_session_id`,`occurred_at`),
  KEY `idx_activity_enrollment_event_user` (`root_user_id`,`occurred_at`),
  CONSTRAINT `fk_activity_enrollment_event_enrollment` FOREIGN KEY (`activity_enrollment_id`) REFERENCES `activity_enrollment` (`activity_enrollment_id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `fk_activity_enrollment_event_session` FOREIGN KEY (`activity_session_id`) REFERENCES `activity_session` (`activity_session_id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `fk_activity_enrollment_event_user` FOREIGN KEY (`root_user_id`) REFERENCES `root_user` (`root_user_id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `chk_activity_enrollment_event_from_status` CHECK (((`from_status` is null) or (`from_status` in (_ascii'PENDING',_ascii'CONFIRMED',_ascii'REJECTED',_ascii'CANCELED')))),
  CONSTRAINT `chk_activity_enrollment_event_generation` CHECK ((`attempt_generation` > 0)),
  CONSTRAINT `chk_activity_enrollment_event_operation` CHECK ((`operation` in (_ascii'ENROLL',_ascii'REVIEW',_ascii'REVIEW_TIMEOUT',_ascii'CANCEL',_ascii'SESSION_CANCEL'))),
  CONSTRAINT `chk_activity_enrollment_event_sequence` CHECK ((`event_sequence` > 0)),
  CONSTRAINT `chk_activity_enrollment_event_to_status` CHECK ((`to_status` in (_ascii'PENDING',_ascii'CONFIRMED',_ascii'REJECTED',_ascii'CANCELED')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- table: activity_session
CREATE TABLE `activity_session` (
  `activity_session_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `activity_version_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` varchar(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `approval_mode` varchar(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `capacity` int unsigned NOT NULL,
  `registration_open_at` datetime(3) NOT NULL,
  `registration_close_at` datetime(3) NOT NULL,
  `cancel_close_at` datetime(3) NOT NULL,
  `review_deadline` datetime(3) DEFAULT NULL,
  `session_start_at` datetime(3) NOT NULL,
  `session_end_at` datetime(3) NOT NULL,
  `allow_reapply` tinyint(1) NOT NULL DEFAULT '0',
  `cancel_reason` varchar(32) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL,
  `cancel_reason_detail` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` datetime(3) NOT NULL,
  `updated_at` datetime(3) NOT NULL,
  PRIMARY KEY (`activity_session_id`),
  UNIQUE KEY `uk_activity_session_business_time` (`activity_version_id`,`session_start_at`),
  KEY `idx_activity_session_visible` (`status`,`session_start_at`,`activity_version_id`),
  KEY `idx_activity_session_registration` (`status`,`registration_open_at`,`registration_close_at`),
  KEY `fk_activity_session_version` (`activity_version_id`),
  CONSTRAINT `fk_activity_session_version` FOREIGN KEY (`activity_version_id`) REFERENCES `activity_definition_version` (`activity_version_id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `chk_activity_session_approval` CHECK ((`approval_mode` in (_ascii'AUTO',_ascii'MANUAL'))),
  CONSTRAINT `chk_activity_session_cancel_reason` CHECK (((`cancel_reason` is null) or (`cancel_reason` in (_ascii'OPERATOR_CANCELED',_ascii'WEATHER',_ascii'VENUE',_ascii'FORCE_MAJEURE',_ascii'OTHER')))),
  CONSTRAINT `chk_activity_session_cancel_shape` CHECK ((((`status` = _ascii'CANCELED') and (`cancel_reason` is not null)) or ((`status` <> _ascii'CANCELED') and (`cancel_reason` is null)))),
  CONSTRAINT `chk_activity_session_cancel_window` CHECK (((`registration_open_at` < `cancel_close_at`) and (`cancel_close_at` <= `session_start_at`))),
  CONSTRAINT `chk_activity_session_capacity` CHECK ((`capacity` > 0)),
  CONSTRAINT `chk_activity_session_other_reason` CHECK (((`cancel_reason` <> _ascii'OTHER') or (`cancel_reason_detail` is not null))),
  CONSTRAINT `chk_activity_session_review_deadline` CHECK ((((`approval_mode` = _ascii'MANUAL') and (`review_deadline` is not null)) or (`approval_mode` = _ascii'AUTO'))),
  CONSTRAINT `chk_activity_session_status` CHECK ((`status` in (_ascii'SCHEDULED',_ascii'OPEN',_ascii'CLOSED',_ascii'CANCELED',_ascii'ENDED'))),
  CONSTRAINT `chk_activity_session_time_order` CHECK (((`registration_open_at` < `registration_close_at`) and (`registration_close_at` <= `session_start_at`) and (`session_start_at` < `session_end_at`)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- table: activity_session_event
CREATE TABLE `activity_session_event` (
  `activity_session_event_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `activity_session_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `event_sequence` int unsigned NOT NULL,
  `operation` varchar(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `from_status` varchar(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `to_status` varchar(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `reason_code` varchar(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `reason_detail` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `request_id` varchar(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `actor_ref` varchar(160) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `occurred_at` datetime(3) NOT NULL,
  PRIMARY KEY (`activity_session_event_id`),
  UNIQUE KEY `uk_activity_session_event_request` (`request_id`),
  UNIQUE KEY `uk_activity_session_event_sequence` (`activity_session_id`,`event_sequence`),
  UNIQUE KEY `uk_activity_session_event_operation` (`activity_session_id`,`operation`),
  KEY `idx_activity_session_event_occurred` (`occurred_at`,`activity_session_id`),
  CONSTRAINT `fk_activity_session_event_session` FOREIGN KEY (`activity_session_id`) REFERENCES `activity_session` (`activity_session_id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `chk_activity_session_event_from_status` CHECK ((`from_status` in (_utf8mb4'SCHEDULED',_utf8mb4'OPEN',_utf8mb4'CLOSED'))),
  CONSTRAINT `chk_activity_session_event_operation` CHECK ((`operation` = _utf8mb4'SESSION_CANCELED')),
  CONSTRAINT `chk_activity_session_event_other_reason` CHECK (((`reason_code` <> _utf8mb4'OTHER') or (`reason_detail` is not null))),
  CONSTRAINT `chk_activity_session_event_reason` CHECK ((`reason_code` in (_utf8mb4'OPERATOR_CANCELED',_utf8mb4'WEATHER',_utf8mb4'VENUE',_utf8mb4'FORCE_MAJEURE',_utf8mb4'OTHER'))),
  CONSTRAINT `chk_activity_session_event_sequence` CHECK ((`event_sequence` > 0)),
  CONSTRAINT `chk_activity_session_event_to_status` CHECK ((`to_status` = _utf8mb4'CANCELED'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

