-- table: command_idempotency
CREATE TABLE `command_idempotency` (
  `command_idempotency_id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `command_name` varchar(96) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NOT NULL,
  `actor_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NOT NULL,
