  `idempotency_key` varchar(191) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `request_digest` char(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `request_digest_scheme` varchar(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'sha256:v0',
  `request_digest_key_id` varchar(128) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL,
  `request_json` json DEFAULT NULL,
  `status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `attempt_count` int unsigned NOT NULL DEFAULT '0',
  `result_json` json DEFAULT NULL,
  `result_ref` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `result_codec_version` varchar(32) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL,
  `result_key_id` varchar(128) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL,
  `error_json` json DEFAULT NULL,
  `last_attempt_request_id` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `lease_owner` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `lease_expires_at` datetime(3) DEFAULT NULL,
  `lease_generation` bigint unsigned NOT NULL DEFAULT '0',
  `started_at` datetime(3) DEFAULT NULL,
  `completed_at` datetime(3) DEFAULT NULL,
  `failed_at` datetime(3) DEFAULT NULL,
  `retain_until` datetime(3) DEFAULT NULL,
  `retention_policy_version` varchar(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'command-retention-v1',
  `tombstoned_at` datetime(3) DEFAULT NULL,
  `tombstone_reason` varchar(64) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL,
  `created_at` datetime(3) NOT NULL,
  `updated_at` datetime(3) NOT NULL,
  PRIMARY KEY (`command_idempotency_id`),
  UNIQUE KEY `uk_command_idempotency_scope` (`command_name`,`actor_id`,`idempotency_key`),
  KEY `idx_command_idempotency_status` (`status`,`updated_at`),
  KEY `idx_command_idempotency_retention` (`retain_until`,`tombstoned_at`),
  KEY `idx_command_idempotency_recovery` (`status`,`lease_expires_at`,`command_idempotency_id`),
  KEY `idx_command_idempotency_digest_crypto` (`request_digest_scheme`,`request_digest_key_id`,`command_idempotency_id`),
  KEY `idx_command_idempotency_result_crypto` (`result_codec_version`,`result_key_id`,`command_idempotency_id`),
  KEY `idx_command_idempotency_retention_policy` (`retention_policy_version`,`retain_until`,`tombstoned_at`),
  KEY `idx_command_idempotency_tombstone` (`tombstoned_at`,`tombstone_reason`,`command_idempotency_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

